fail=0
[ -n "$(bash bin/checkout 1000)" ] || { echo "checkout prints nothing"; fail=1; }
# CHK-310: 10% tax must be applied exactly once (spec: 1000 -> 1100)
for c in "1000 1100" "0 0" "200 220"; do
  set -- $c
  got=$(bash bin/checkout "$1")
  [ "$got" = "$2" ] || { echo "checkout $1: expected $2, got $got"; fail=1; }
done
exit $fail

